package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ResponseTypesJsonVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property response types json of trusted client ")
  void test_response_types_json_v_o_builder() {
    Assertions.assertFalse(ResponseTypesJsonVO.nullValue().getResponseTypesJson().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ResponseTypesJsonVO.tryFrom(null).getResponseTypesJson().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        ResponseTypesJsonVO.from("one").getResponseTypesJson().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ResponseTypesJsonVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ResponseTypesJsonVO.from("one").toString());
  }
}
